import java.util.HashMap;

public class Main {
    public static void main(String[] args) {
        HashMap<String, Integer> gia = new HashMap<>();
        gia.put("tao", 30);
        gia.put("cam", 25);
        for (var e : gia.entrySet())
            System.out.println(e.getKey() + " = " + e.getValue());
    }
}
